var n=`0385-haring-met-uitjes`;var t=`world-0385`;var r=`NL`;var s=`western-europe`;var a=4;var d=10;var o={en:`Haring met Uitjes`,ua:`Оселедець із цибулею`};var g={en:`A traditional Netherlands dish made with salted herring, red onion, fermented cucumber, rye bread. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Нідерланди. Основні інгредієнти: солоний оселедець, червона цибуля, квашений огірок, житній хліб. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:7,i:[[`salted-herring`,520,`g`],[`red-onion`,170,`g`],[`fermented-cucumber`,220,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`rye-bread`,330,`g`],[`lemon-juice`,20,`ml`]]}];var c={slug:n,id:t,country:`NL`,region:s,servings:4,minutes:10,title:o,text:g,steps:h};export{r as country,c as default,t as id,d as minutes,s as region,a as servings,n as slug,h as steps,g as text,o as title};